sigjmp_buf env_state;
#define E_FATAL_ERROR 10

// Function deep in stack detects failure
void deep_failure() {
    // Escapes stack immediately, restoring signal mask
    siglongjmp(env_state, E_FATAL_ERROR);
}

// Set up jump environment, save signal mask (arg 1)
int jump_result = sigsetjmp(env_state, 1);

if (jump_result == 0) {
    // Path 1: Initial call/setup
    deep_failure();
} else {
    // Path 2: Non-local jump target (jump_result == return value)
    if (jump_result == E_FATAL_ERROR) {
        // Error handling logic
    }
}
